PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "site" ("id" INTEGER NOT NULL PRIMARY KEY, "name" VARCHAR(255) NOT NULL, "building" VARCHAR(255) NOT NULL, "physical_address" VARCHAR(255) NOT NULL, "city" VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "contact" ("id" INTEGER NOT NULL PRIMARY KEY, "name" VARCHAR(255) NOT NULL, "phone" VARCHAR(255) NOT NULL, "mail" VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "machine" ("id" INTEGER NOT NULL PRIMARY KEY, "serial" VARCHAR(255) NOT NULL, "asset" VARCHAR(255) NOT NULL, "sku" VARCHAR(255) NOT NULL, "model" VARCHAR(255) NOT NULL, "ip_addr" VARCHAR(255) NOT NULL, "hostname" VARCHAR(255) NOT NULL, "subnet_mask" VARCHAR(255), "gateway" VARCHAR(255), "mac_addr" VARCHAR(255), "site_id" INTEGER, "contact_id" INTEGER, "status" VARCHAR(255) NOT NULL, "collection_method" VARCHAR(255) NOT NULL, FOREIGN KEY ("site_id") REFERENCES "site" ("id"), FOREIGN KEY ("contact_id") REFERENCES "contact" ("id"));
CREATE TABLE IF NOT EXISTS "helpdeskcase" ("id" INTEGER NOT NULL PRIMARY KEY, "ticket" INTEGER NOT NULL, "description" VARCHAR(255) NOT NULL, "start_date" DATETIME NOT NULL, "end_date" DATETIME NOT NULL, "machine_associated_id" INTEGER, "site_associated_id" INTEGER, "contact_associated_id" INTEGER, FOREIGN KEY ("machine_associated_id") REFERENCES "machine" ("id"), FOREIGN KEY ("site_associated_id") REFERENCES "site" ("id"), FOREIGN KEY ("contact_associated_id") REFERENCES "contact" ("id"));
CREATE TABLE IF NOT EXISTS "channelcase" ("id" INTEGER NOT NULL PRIMARY KEY, "n_case" INTEGER NOT NULL, "work_order" VARCHAR(255) NOT NULL, "machine_associated_id" INTEGER, "helpdesk_case_associated_id" INTEGER, "description" VARCHAR(255), "status" VARCHAR(255) NOT NULL, "creation_date" DATETIME NOT NULL, "close_date" DATETIME, FOREIGN KEY ("machine_associated_id") REFERENCES "machine" ("id"), FOREIGN KEY ("helpdesk_case_associated_id") REFERENCES "helpdeskcase" ("id"));
CREATE TABLE IF NOT EXISTS "removedmachine" ("id" INTEGER NOT NULL PRIMARY KEY, "serial" VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "consumablelevel" ("id" INTEGER NOT NULL PRIMARY KEY, "machine_id" INTEGER, "removed_machine_id" INTEGER, "detection_date" DATETIME NOT NULL, "magenta_level" INTEGER NOT NULL, "cyan_level" INTEGER NOT NULL, "yellow_level" INTEGER NOT NULL, "black_level" INTEGER NOT NULL, FOREIGN KEY ("machine_id") REFERENCES "machine" ("id"), FOREIGN KEY ("removed_machine_id") REFERENCES "removedmachine" ("id"));
CREATE TABLE IF NOT EXISTS "machinechange" ("id" INTEGER NOT NULL PRIMARY KEY, "old_serial" VARCHAR(255) NOT NULL, "new_serial" VARCHAR(255) NOT NULL, "case_associated_id" INTEGER, "site_associated_id" INTEGER, "change_date" DATETIME, "msl_sent" INTEGER, "dcc_updated" INTEGER, FOREIGN KEY ("case_associated_id") REFERENCES "channelcase" ("id"), FOREIGN KEY ("site_associated_id") REFERENCES "site" ("id"));
CREATE TABLE IF NOT EXISTS "nrd" ("id" INTEGER NOT NULL PRIMARY KEY, "machine_associated_id" INTEGER NOT NULL, "last_collection_date" DATETIME NOT NULL, "has_conectivity" INTEGER, "is_machine_change" INTEGER, "is_unknown_reason" INTEGER, FOREIGN KEY ("machine_associated_id") REFERENCES "machine" ("id"));
CREATE TABLE IF NOT EXISTS "osafov" ("id" INTEGER NOT NULL PRIMARY KEY, "n_case" INTEGER NOT NULL, "description" VARCHAR(255) NOT NULL, "creation_date" VARCHAR(255) NOT NULL, "machine_associated" VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "osarr" ("id" INTEGER NOT NULL PRIMARY KEY, "n_case" INTEGER NOT NULL, "description" VARCHAR(255) NOT NULL, "creation_date" VARCHAR(255) NOT NULL, "machine_associated" VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "osatask" ("id" INTEGER NOT NULL PRIMARY KEY, "n_case" INTEGER NOT NULL, "description" VARCHAR(255) NOT NULL, "creation_date" VARCHAR(255) NOT NULL, "machine_associated" VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "supplyorder" ("id" INTEGER NOT NULL PRIMARY KEY, "n_order" INTEGER NOT NULL, "machine_id" INTEGER, "removed_machine_id" INTEGER, "cyan_cartridge" VARCHAR(255), "magenta_cartridge" VARCHAR(255), "yellow_cartridge" VARCHAR(255), "black_cartridge" VARCHAR(255), "creation_date" DATETIME NOT NULL, "arrival_date" DATETIME, "close_date" DATETIME, FOREIGN KEY ("machine_id") REFERENCES "machine" ("id"), FOREIGN KEY ("removed_machine_id") REFERENCES "removedmachine" ("id"));
CREATE INDEX "machine_site_id" ON "machine" ("site_id");
CREATE INDEX "machine_contact_id" ON "machine" ("contact_id");
CREATE INDEX "helpdeskcase_machine_associated_id" ON "helpdeskcase" ("machine_associated_id");
CREATE INDEX "helpdeskcase_site_associated_id" ON "helpdeskcase" ("site_associated_id");
CREATE INDEX "helpdeskcase_contact_associated_id" ON "helpdeskcase" ("contact_associated_id");
CREATE INDEX "channelcase_machine_associated_id" ON "channelcase" ("machine_associated_id");
CREATE INDEX "channelcase_helpdesk_case_associated_id" ON "channelcase" ("helpdesk_case_associated_id");
CREATE INDEX "consumablelevel_machine_id" ON "consumablelevel" ("machine_id");
CREATE INDEX "consumablelevel_removed_machine_id" ON "consumablelevel" ("removed_machine_id");
CREATE INDEX "machinechange_case_associated_id" ON "machinechange" ("case_associated_id");
CREATE INDEX "machinechange_site_associated_id" ON "machinechange" ("site_associated_id");
CREATE INDEX "nrd_machine_associated_id" ON "nrd" ("machine_associated_id");
CREATE INDEX "supplyorder_machine_id" ON "supplyorder" ("machine_id");
CREATE INDEX "supplyorder_removed_machine_id" ON "supplyorder" ("removed_machine_id");
COMMIT;
